#!/usr/bin/env python3
"""Build a reviewable, credential-free worktree snapshot. No application is started."""
import argparse,datetime,hashlib,json,re,shutil,subprocess,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
sha=lambda b:hashlib.sha256(b).hexdigest()
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--out',default='tmp/ojj-qq-agent-project-handover-20261028-v1');args=ap.parse_args()
    out=Path(args.out).resolve();out.mkdir(parents=True,exist_ok=True)
    if (out/'MANIFEST.json').exists():raise SystemExit('Output exists; choose a new directory')
    branch=subprocess.check_output(['git','branch','--show-current'],cwd=ROOT,text=True).strip();commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
    records=[];date='2026-10-28'
    def put(rel,data,source=None,source_bytes=None,transform=None):
        b=data.encode() if isinstance(data,str) else data
        if re.search(rb'sk-[A-Za-z0-9]{20,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----',b):raise ValueError('Credential-like content: '+rel)
        dest=out/rel;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(b)
        records.append({'source':source or 'generated by scripts/build_handover.py','delivered':rel,'source_sha256':sha(source_bytes if source_bytes is not None else b),'delivered_sha256':sha(b),'bytes':len(b),'transformation':transform or 'none'})
    def copy(f,rel,redact=False):
        b=f.read_bytes();data=b;transform=None
        if redact and f.suffix in ['.json','.md','.html','.log','.txt']:
            data=re.sub(rb'/workspace/[^\s"<>\)]+',b'<WORKSPACE_PATH>',b)
            data=re.sub(rb'/tmp/[^\s"<>\)]+',b'<TEMP_PATH>',data)
            if data!=b:transform='cloud absolute paths replaced; facts and scores preserved'
        put(rel,data,str(f.relative_to(ROOT)),b,transform)
    for f in sorted((ROOT/'handover').rglob('*')):
        if f.is_file():
            raw=f.read_bytes();data=raw
            if f.suffix=='.md':data=raw.decode().replace('@DATE@',date).replace('@COMMIT@',commit).replace('@BRANCH@',branch).encode()
            put(str(f.relative_to(ROOT/'handover')),data,str(f.relative_to(ROOT)),raw,'template metadata' if data!=raw else None)
    app='apps/ojj-qq-agent/'
    for folder in ['src','scripts','tests','assets','docs','public','data/knowledge','reports','handover']:
        for f in sorted((ROOT/folder).rglob('*')):
            if f.is_file() and not f.is_symlink() and '__pycache__' not in f.parts and f.suffix not in ['.pyc','.log']:
                copy(f,app+str(f.relative_to(ROOT)))
    for name in ['README.md','package.json','package-lock.json','requirements-multimodal.txt','requirements-test.txt','config.example.json','.env.example','.gitignore','LICENSE']:
        copy(ROOT/name,app+name)
    runs=['response-quality-live','response-quality-after','holdout-before','holdout-after','holdout-final','numeric-regression-final','delivery-memory-live','delivery-memory-reserve','task-reliability-live','task-reliability-reserve']
    for run in runs:
        for f in sorted((ROOT/'tmp'/run).rglob('*')):
            if f.is_file() and not set(f.relative_to(ROOT/'tmp'/run).parts)&{'isolated-data','memory','tasks','delivery'}:copy(f,'evidence/'+str(f.relative_to(ROOT/'tmp')),True)
    for prefix in ['task-reliability-summary','delivery-memory-summary','numeric-quality-comparison','response-quality-comparison','hybrid-comparison']:
        for ext in ['.md','.html','.json']:
            f=ROOT/'tmp'/(prefix+ext)
            if f.exists():copy(f,'evidence/'+f.name,True)
    for name in ['task-reliability-final-tests.log','task-reliability-mechanism-comparison.json','holdout-errata.json','hybrid-final-live.json','hybrid-final-live.html']:
        f=ROOT/'tmp'/name
        if f.exists():copy(f,'evidence/'+name,True)
    for name in ['handover-node-tests.log','handover-python-tests.log']:
        f=ROOT/'tmp'/name
        if f.exists():copy(f,'evidence/'+name,True)
    verify=ROOT/'tmp/handover-verification.json'
    put('evidence/PACKAGE_VERIFICATION.json',verify.read_bytes() if verify.exists() else json.dumps({'status':'not_run','note':'Package verification pending, no result fabricated.'}))
    put('evidence/README.md','# 证据导航\n\n最新：[任务可靠性](task-reliability-summary.html)。第一批失败和最终换题结果均保留。其他历史报告按原目录保留。历史源码快照、隔离运行数据库与真实QQ凭据不在本包；历史文档内指向这些未打包明细的路径只说明当时的证据来源。\n\n本次解包复现见 PACKAGE_VERIFICATION.json；历史测试不因重新打包变成新测试。\n')
    datasets=[]
    for run in ['response-quality-after','holdout-final','delivery-memory-live','delivery-memory-reserve','task-reliability-live','task-reliability-reserve']:
        source=ROOT/'tmp'/run/'results.json';report=json.loads(source.read_text());cases=report['cases']
        rel=f'data/scenarios/{run}.jsonl';put(rel,'\n'.join(json.dumps({'suite':run,**c},ensure_ascii=False) for c in cases)+'\n',str(source.relative_to(ROOT)),source.read_bytes(),'cases exported; no answers added')
        datasets.append({'file':rel,'scenarios':len(cases),'turns':sum(len(c['turns']) for c in cases),'data_policy':'synthetic_test_inputs','status':'previously_evaluated_not_unseen'})
    put('data/scenarios/manifest.json',json.dumps({'datasets':datasets,'note':'Holdout includes planned repeats; do not sum these as independent accuracy samples.'},ensure_ascii=False,indent=2))
    labels=['media_ownership','memory_lifecycle','task_persistence','format_transition','tool_protocol','reference_binding','temporal_intent','latency','presentation']
    put('tests/badcase_framework/taxonomy.json',json.dumps({'labels':labels,'severity':{'S1':'阻断核心任务','S2':'错误操作或归属风险','S3':'体验问题'}},ensure_ascii=False,indent=2))
    cases=[]
    for i,(label,name,obs,expected) in enumerate([
        ('media_ownership','群文件归属','两个成员文件被合并给后一个人','同群不同成员独立处理'),('memory_lifecycle','过期来源','超过容量后失效信息通过旧聊天出现','持续过滤失效来源'),('task_persistence','草稿重启','重启丢失草稿','恢复已保存草稿')],1):
        cases.append({'id':f'BC{i:03}','label':label,'severity':'S2','observed':obs,'expected':expected,'original_verdict':'fail','resolution':'same deterministic before/after reproduction passed','evidence_refs':['evidence/task-reliability-mechanism-comparison.json']})
    for i,(cid,label) in enumerate([('oldest-partial-correction','tool_protocol'),('expiry-after-many-notes','temporal_intent'),('two-members-interleaved-change','reference_binding'),('draft-survives-two-corrections','format_transition')],4):
        r=json.loads((ROOT/'tmp/task-reliability-live/reviews.json').read_text())[cid]
        cases.append({'id':f'BC{i:03}','label':label,'severity':'S1','observed':r['rationale'],'expected':'执行用户请求并给出有依据的最终回答','original_verdict':'fail','resolution':'generic mechanism repaired; unit regression and different fresh scenarios passed, original result retained','source_case':cid,'evidence_refs':['evidence/task-reliability-live/results.json','evidence/task-reliability-live/reviews.json','evidence/task-reliability-reserve/results.json']})
    put('tests/badcase_framework/cases.json',json.dumps(cases,ensure_ascii=False,indent=2))
    put('tests/badcase_framework/case.schema.json',json.dumps({'$schema':'https://json-schema.org/draft/2020-12/schema','type':'object','required':['id','label','severity','observed','expected','resolution','evidence_refs'],'properties':{'id':{'type':'string','pattern':'^BC[0-9]{3}$'},'label':{'enum':labels},'severity':{'enum':['S1','S2','S3']},'evidence_refs':{'type':'array','items':{'type':'string'}}}},ensure_ascii=False,indent=2))
    put('tests/badcase_framework/scorecard.schema.json',json.dumps({'type':'object','required':['case_id','verdict','evaluator','evidence_refs'],'properties':{'verdict':{'enum':['pass','fail','service_error','unscorable','not_run']},'evaluator':{'enum':['deterministic','codex_review','independent_human']}}},indent=2))
    # Generate editable, text-only design slides from this project's own material.
    from pptx import Presentation
    from pptx.util import Inches,Pt
    from pptx.dml.color import RGBColor
    decks=[('design-and-scope',[('项目目标',['QQ上的单主Agent助手','用程序约束执行，用模型理解语言','真实结果与语言承诺分开记录']),('能力范围',['对话、记忆、核算与资料检索','PPT / Word / Excel真实文件生成','已有语音、图片、歌曲与翻唱适配']),('设计原则',['群成员与任务归属隔离','记忆保存与上下文窗口分开','工具效果必须有真实回执']),('证据与边界',['最终新题10场景32轮：10项达标','此前12题4项失败仍完整保留','真实QQ验收与多实例能力尚待完善'])]),('architecture-and-lifecycle',[('运行链路',['OneBot → 访问检查与文件合并','任务指令直接查询状态','其他请求 → Brain → 意图 → 单主Agent']),('程序工作流',['权限、参数、依赖、预算由程序检查','数值核算使用有理数工具','文件任务进入持久队列']),('任务恢复',['任务与交付日志启动时校准','未开始的文件可取消','已有文件从上传步骤继续']),('交付事实',['生成成功不等于上传成功','接口上传成功不等于对方已读','结果未知时禁止自动重发']),('记忆与验收',['40条是上下文选择窗口，不是存储上限','失效记录保留来源标记','代码回归、模型新题、真实QQ分层验收'])])]
    for name,slides in decks:
        prs=Presentation();prs.slide_width=Inches(13.333);prs.slide_height=Inches(7.5)
        for n,(title,bullets) in enumerate(slides,1):
            sl=prs.slides.add_slide(prs.slide_layouts[6]);sl.background.fill.solid();sl.background.fill.fore_color.rgb=RGBColor.from_string('102438')
            for x,y,w,h,text,size,color in [(0.7,0.55,12,1,title,32,'FFFFFF'),(0.75,1.9,11.8,4.4,'\n\n'.join(bullets),25,'D7E8F3'),(0.75,6.85,11.8,.35,f'ojj QQ Agent · 当前实现说明 · {date} · {n}',12,'76B9BC')]:
                tf=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h)).text_frame;tf.word_wrap=True;tf.text=text
                for p in tf.paragraphs:p.font.name='Noto Sans CJK SC';p.font.size=Pt(size);p.font.color.rgb=RGBColor.from_string(color)
        import io
        b=io.BytesIO();prs.save(b);put(f'materials/ojj-{name}-v1.pptx',b.getvalue())
    for folder in ['handover-design-preview','handover-architecture-preview']:
        for f in sorted((ROOT/'tmp'/folder).glob('*.pdf')):
            copy(f,'materials/'+f.name)
        contact=ROOT/'tmp'/folder/'contact.png'
        if contact.exists():copy(contact,'materials/'+folder+'.png')
    manifest={'package':out.name,'created':date,'source_commit':commit,'source_branch':branch,'source_state':'worktree_snapshot_including_uncommitted_changes','worktree_status':subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True).splitlines(),'reference':'AstrBot handover structure only; no reference source copied','file_count':len(records),'files':records}
    (out/'MANIFEST.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
    hashes=[(r['delivered_sha256'],r['delivered']) for r in records]+[(sha((out/'MANIFEST.json').read_bytes()),'MANIFEST.json')]
    (out/'SHA256SUMS.txt').write_text(''.join(f'{h}  {p}\n' for h,p in sorted(hashes,key=lambda x:x[1])))
    archive=out.with_suffix('.zip')
    with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
        for f in sorted(out.rglob('*')):
            if f.is_file():z.write(f,out.name+'/'+str(f.relative_to(out)))
    archive.with_suffix('.zip.sha256').write_text(sha(archive.read_bytes())+'  '+archive.name+'\n')
    print(json.dumps({'directory':str(out),'zip':str(archive),'files':len(records),'bytes':archive.stat().st_size},ensure_ascii=False))
if __name__=='__main__':main()
